55	namespace {
56	enum {
57	  // Before reading first byte of message length
58	  BT_MSG_PREV_READ_LENGTH,
59	  // Reading 4 bytes message length
60	  BT_MSG_READ_LENGTH,
61	  // Reading message payload following message length
62	  BT_MSG_READ_PAYLOAD
63	};
64	} // namespace
65	
66	PeerConnection::PeerConnection(cuid_t cuid, const std::shared_ptr<Peer>& peer,
67	                               const std::shared_ptr<SocketCore>& socket)
68	    : cuid_(cuid),
69	      peer_(peer),
70	      socket_(socket),
71	      msgState_(BT_MSG_PREV_READ_LENGTH),
72	      bufferCapacity_(MAX_BUFFER_CAPACITY),
73	      resbuf_(make_unique<unsigned char[]>(bufferCapacity_)),
74	      resbufLength_(0),
75	      currentPayloadLength_(0),
76	      resbufOffset_(0),
77	      msgOffset_(0),
78	      socketBuffer_(socket),
79	      encryptionEnabled_(false),
80	      prevPeek_(false)
81	{
82	}
83	
84	PeerConnection::~PeerConnection() = default;
85	
86	void PeerConnection::pushBytes(std::vector<unsigned char> data,
87	                               std::unique_ptr<ProgressUpdate> progressUpdate)
88	{
89	  if (encryptionEnabled_) {
90	    encryptor_->encrypt(data.size(), data.data(), data.data());
91	  }
92	  socketBuffer_.pushBytes(std::move(data), std::move(progressUpdate));
93	}
94	
95	bool PeerConnection::receiveMessage(unsigned char* data, size_t& dataLength)
96	{
97	  while (1) {
98	    bool done = false;
99	    size_t i;
100	    for (i = resbufOffset_; i < resbufLength_ && !done; ++i) {
101	      unsigned char c = resbuf_[i];
102	      switch (msgState_) {
103	      case (BT_MSG_PREV_READ_LENGTH):
104	        msgOffset_ = i;
105	        currentPayloadLength_ = 0;
106	        msgState_ = BT_MSG_READ_LENGTH;
107	      // Fall through
108	      case (BT_MSG_READ_LENGTH):
109	        currentPayloadLength_ <<= 8;
110	        currentPayloadLength_ += c;
111	        // The message length is uint32_t
112	        if (i - msgOffset_ == 3) {
113	          if (currentPayloadLength_ + 4 > bufferCapacity_) {
114	            throw DL_ABORT_EX(fmt(EX_TOO_LONG_PAYLOAD, currentPayloadLength_));
115	          }
116	          if (currentPayloadLength_ == 0) {
117	            // Length == 0 means keep-alive message.
118	            done = true;
119	            msgState_ = BT_MSG_PREV_READ_LENGTH;
120	          }
121	          else {
122	            msgState_ = BT_MSG_READ_PAYLOAD;
123	          }
124	        }
125	        break;
126	      case (BT_MSG_READ_PAYLOAD):
127	        // We chose the bufferCapacity_ so that whole message,
128	        // including 4 bytes length and payload, in it. So here we
129	        // just make sure that it happens.
130	        if (resbufLength_ - msgOffset_ >= 4 + currentPayloadLength_) {
131	          i = msgOffset_ + 4 + currentPayloadLength_ - 1;
132	          done = true;
133	          msgState_ = BT_MSG_PREV_READ_LENGTH;
134	        }
135	        else {
136	          // We need another read.
137	          i = resbufLength_ - 1;
138	        }
139	        break;
140	      }
141	    }
142	    resbufOffset_ = i;
143	    if (done) {
144	      if (data) {
145	        std::copy_n(resbuf_.get() + msgOffset_ + 4, currentPayloadLength_,
146	                    data);
147	      }
148	      dataLength = currentPayloadLength_;
149	      return true;
150	    }
151	    else {
152	      assert(resbufOffset_ == resbufLength_);
153	      if (resbufLength_ != 0) {
154	        if (resbufLength_ - msgOffset_ == currentPayloadLength_ + 4) {
155	          // All bytes in buffer have been processed, so clear it
156	          // away.
157	          resbufLength_ = 0;
158	          resbufOffset_ = 0;
159	          msgOffset_ = 0;
160	        }
161	        else {
162	          // Shift buffer so that resbuf_[msgOffset_] moves to
163	          // rebuf_[0].
164	          memmove(resbuf_.get(), resbuf_.get() + msgOffset_,
165	                  resbufLength_ - msgOffset_);
166	          resbufLength_ -= msgOffset_;
167	          resbufOffset_ = resbufLength_;
168	          msgOffset_ = 0;
169	        }
170	      }
171	      size_t nread;
172	      // To reduce the amount of copy involved in buffer shift, large
173	      // payload will be read exactly.
174	      if (currentPayloadLength_ > 4_k) {
175	        nread = currentPayloadLength_ + 4 - resbufLength_;
176	      }
177	      else {
178	        nread = bufferCapacity_ - resbufLength_;
179	      }
180	      readData(resbuf_.get() + resbufLength_, nread, encryptionEnabled_);
181	      if (nread == 0) {
182	        if (socket_->wantRead() || socket_->wantWrite()) {
183	          break;
184	        }
185	        else {
186	          peer_->setDisconnectedGracefully(true);
187	          throw DL_ABORT_EX(EX_EOF_FROM_PEER);
188	        }
189	      }
190	      else {
191	        resbufLength_ += nread;
192	      }
193	    }
194	  }
195	  return false;
196	}
197	
198	bool PeerConnection::receiveHandshake(unsigned char* data, size_t& dataLength,
199	                                      bool peek)
200	{
201	  if (BtHandshakeMessage::MESSAGE_LENGTH < resbufLength_) {
202	    throw DL_ABORT_EX(
203	        "More than BtHandshakeMessage::MESSAGE_LENGTH bytes are buffered.");
204	  }
205	  bool retval = true;
206	  size_t remaining = BtHandshakeMessage::MESSAGE_LENGTH - resbufLength_;
207	  if (remaining > 0) {
208	    size_t temp = remaining;
209	    readData(resbuf_.get() + resbufLength_, remaining, encryptionEnabled_);
210	    if (remaining == 0 && !socket_->wantRead() && !socket_->wantWrite()) {
211	      // we got EOF
212	      A2_LOG_DEBUG(fmt("CUID#%" PRId64
213	                       " - In PeerConnection::receiveHandshake(), remain=%lu",
214	                       cuid_, static_cast<unsigned long>(temp)));
215	      peer_->setDisconnectedGracefully(true);
216	      throw DL_ABORT_EX(EX_EOF_FROM_PEER);
217	    }
218	    resbufLength_ += remaining;
219	    if (BtHandshakeMessage::MESSAGE_LENGTH > resbufLength_) {
220	      retval = false;
221	    }
222	  }
223	  size_t writeLength = std::min(resbufLength_, dataLength);
224	  std::copy_n(resbuf_.get(), writeLength, data);
225	  dataLength = writeLength;
226	  if (retval && !peek) {
227	    resbufLength_ = 0;
228	  }
229	  return retval;
230	}
231	
232	void PeerConnection::readData(unsigned char* data, size_t& length,
233	                              bool encryption)
234	{
235	  socket_->readData(data, length);
236	  if (encryption) {
237	    decryptor_->encrypt(length, data, data);
238	  }
239	}
240	
241	void PeerConnection::enableEncryption(std::unique_ptr<ARC4Encryptor> encryptor,
242	                                      std::unique_ptr<ARC4Encryptor> decryptor)
243	{
244	  encryptor_ = std::move(encryptor);
245	  decryptor_ = std::move(decryptor);
246	
247	  encryptionEnabled_ = true;
248	}
249	
250	void PeerConnection::presetBuffer(const unsigned char* data, size_t length)
251	{
252	  size_t nwrite = std::min(bufferCapacity_, length);
253	  std::copy_n(data, nwrite, resbuf_.get());
254	  resbufLength_ = length;
255	}
256	
257	bool PeerConnection::sendBufferIsEmpty() const
258	{
259	  return socketBuffer_.sendBufferIsEmpty();
260	}
261	
262	size_t PeerConnection::getBufferEntrySize() const
263	{
264	  return socketBuffer_.getBufferEntrySize();
265	}
266	
267	ssize_t PeerConnection::sendPendingData()
268	{
269	  ssize_t writtenLength = socketBuffer_.send();
270	  A2_LOG_DEBUG(fmt("sent %ld byte(s).", static_cast<long int>(writtenLength)));
271	  return writtenLength;
272	}
273	
274	const unsigned char* PeerConnection::getMsgPayloadBuffer() const
275	{
276	  return resbuf_.get() + msgOffset_ + 4;
277	}
278	
279	void PeerConnection::reserveBuffer(size_t minSize)
280	{
281	  if (bufferCapacity_ < minSize) {
282	    bufferCapacity_ = minSize;
283	    auto buf = make_unique<unsigned char[]>(bufferCapacity_);
284	    std::copy_n(resbuf_.get(), resbufLength_, buf.get());
285	    resbuf_ = std::move(buf);
286	  }
287	}
