63	
64	PeerReceiveHandshakeCommand::PeerReceiveHandshakeCommand(
65	    cuid_t cuid, const std::shared_ptr<Peer>& peer, DownloadEngine* e,
66	    const std::shared_ptr<SocketCore>& s,
67	    std::unique_ptr<PeerConnection> peerConnection)
68	    : PeerAbstractCommand{cuid, peer, e, s},
69	      peerConnection_{std::move(peerConnection)}
70	{
71	  if (peerConnection_) {
72	    if (peerConnection_->getBufferLength() > 0) {
73	      setStatus(Command::STATUS_ONESHOT_REALTIME);
74	      getDownloadEngine()->setNoWait(true);
75	    }
76	  }
77	  else {
78	    peerConnection_ = make_unique<PeerConnection>(cuid, getPeer(), getSocket());
79	  }
80	}
81	
82	PeerReceiveHandshakeCommand::~PeerReceiveHandshakeCommand() = default;
83	
84	bool PeerReceiveHandshakeCommand::exitBeforeExecute()
85	{
86	  return getDownloadEngine()->isHaltRequested() ||
87	         getDownloadEngine()->getRequestGroupMan()->downloadFinished();
88	}
89	
90	bool PeerReceiveHandshakeCommand::executeInternal()
91	{
92	  // Handle tracker's NAT-checking feature
93	  if (peerConnection_->getBufferLength() < 48) {
94	    size_t dataLength = 0;
95	    // Ignore return value. The received data is kept in
96	    // PeerConnection object because of peek = true.
97	    peerConnection_->receiveHandshake(nullptr, dataLength, true);
98	  }
99	  if (peerConnection_->getBufferLength() >= 48) {
100	    const unsigned char* data = peerConnection_->getBuffer();
101	    // check info_hash
102	    std::string infoHash(&data[28], &data[28 + INFO_HASH_LENGTH]);
103	
104	    std::shared_ptr<DownloadContext> downloadContext =
105	        getDownloadEngine()->getBtRegistry()->getDownloadContext(infoHash);
106	    if (!downloadContext) {
107	      throw DL_ABORT_EX(
108	          fmt("Unknown info hash %s", util::toHex(infoHash).c_str()));
109	    }
110	    auto btObject = getDownloadEngine()->getBtRegistry()->get(
111	        downloadContext->getOwnerRequestGroup()->getGID());
112	    const std::shared_ptr<BtRuntime>& btRuntime = btObject->btRuntime;
113	    const std::shared_ptr<PieceStorage>& pieceStorage = btObject->pieceStorage;
114	    const std::shared_ptr<PeerStorage>& peerStorage = btObject->peerStorage;
115	    if (!btRuntime->ready()) {
116	      throw DL_ABORT_EX(
117	          fmt("Unknown info hash %s", util::toHex(infoHash).c_str()));
118	    }
119	    if (btRuntime->isHalt()) {
120	      A2_LOG_DEBUG("Info hash found but the download is over."
121	                   " Dropping connection.");
122	      return true;
123	    }
124	    NetStat& stat = downloadContext->getNetStat();
125	    const int maxDownloadLimit =
126	        downloadContext->getOwnerRequestGroup()->getMaxDownloadSpeedLimit();
127	    int thresholdSpeed =
128	        downloadContext->getOwnerRequestGroup()->getOption()->getAsInt(
129	            PREF_BT_REQUEST_PEER_SPEED_LIMIT);
130	    if (maxDownloadLimit > 0) {
131	      thresholdSpeed = std::min(maxDownloadLimit, thresholdSpeed);
132	    }
133	
134	    if ((!pieceStorage->downloadFinished() &&
135	         stat.calculateDownloadSpeed() < thresholdSpeed) ||
136	        btRuntime->lessThanMaxPeers()) {
137	      // TODO addPeer and checkoutPeer must be "atomic", in a sense
138	      // that the added peer must be checked out.
139	      if (peerStorage->addAndCheckoutPeer(getPeer(), getCuid())) {
140	        getDownloadEngine()->addCommand(make_unique<PeerInteractionCommand>(
141	            getCuid(), downloadContext->getOwnerRequestGroup(), getPeer(),
142	            getDownloadEngine(), btRuntime, pieceStorage, peerStorage,
143	            getSocket(), PeerInteractionCommand::RECEIVER_WAIT_HANDSHAKE,
144	            std::move(peerConnection_)));
145	        A2_LOG_DEBUG(
146	            fmt(MSG_INCOMING_PEER_CONNECTION, getCuid(), getPeer()->usedBy()));
147	      }
148	    }
149	    return true;
150	  }
151	  else {
152	    addCommandSelf();
153	    return false;
154	  }
155	}
