62	  pstrlen_ = 19;
63	  std::copy_n(BT_PSTR, pstr_.size(), std::begin(pstr_));
64	  std::fill(std::begin(reserved_), std::end(reserved_), 0);
65	  // fast extension
66	  reserved_[7] |= 0x04u;
67	  // extended messaging
68	  reserved_[5] |= 0x10u;
69	}
70	
71	std::unique_ptr<BtHandshakeMessage>
72	BtHandshakeMessage::create(const unsigned char* data, size_t dataLength)
73	{
74	  auto msg = make_unique<BtHandshakeMessage>();
75	  msg->pstrlen_ = data[0];
76	  std::copy_n(&data[1], msg->pstr_.size(), std::begin(msg->pstr_));
77	  std::copy_n(&data[20], msg->reserved_.size(), std::begin(msg->reserved_));
78	  std::copy_n(&data[28], msg->infoHash_.size(), std::begin(msg->infoHash_));
79	  std::copy_n(&data[48], msg->peerId_.size(), std::begin(msg->peerId_));
80	
81	  return msg;
82	}
83	
84	std::vector<unsigned char> BtHandshakeMessage::createMessage()
85	{
86	  auto msg = std::vector<unsigned char>(MESSAGE_LENGTH);
87	  auto dst = msg.data();
88	  *dst++ = pstrlen_;
89	  dst = std::copy(std::begin(pstr_), std::end(pstr_), dst);
90	  dst = std::copy(std::begin(reserved_), std::end(reserved_), dst);
91	  dst = std::copy(std::begin(infoHash_), std::end(infoHash_), dst);
92	  std::copy(std::begin(peerId_), std::end(peerId_), dst);
93	  return msg;
94	}
95	
96	std::string BtHandshakeMessage::toString() const
97	{
98	  return fmt("%s peerId=%s, reserved=%s", NAME,
99	             util::percentEncode(peerId_.data(), peerId_.size()).c_str(),
100	             util::toHex(reserved_.data(), reserved_.size()).c_str());
101	}
102	
103	bool BtHandshakeMessage::isFastExtensionSupported() const
104	{
105	  return reserved_[7] & 0x04u;
106	}
107	
108	bool BtHandshakeMessage::isExtendedMessagingEnabled() const
109	{
110	  return reserved_[5] & 0x10u;
111	}
112	
113	bool BtHandshakeMessage::isDHTEnabled() const { return reserved_[7] & 0x01u; }
114	
115	void BtHandshakeMessage::setInfoHash(const unsigned char* infoHash)
116	{
117	  std::copy_n(infoHash, infoHash_.size(), std::begin(infoHash_));
118	}
119	
120	void BtHandshakeMessage::setPeerId(const unsigned char* peerId)
121	{
122	  std::copy_n(peerId, peerId_.size(), std::begin(peerId_));
123	}
