151	void PeerAbstractCommand::disableWriteCheckSocket()
152	{
153	  if (checkSocketIsWritable_) {
154	    e_->deleteSocketForWriteCheck(writeCheckTarget_, this);
155	    checkSocketIsWritable_ = false;
156	    writeCheckTarget_.reset();
157	  }
158	}
