171	        writeCheckTarget_ = socket;
172	      }
173	    }
174	    else {
175	      e_->addSocketForWriteCheck(socket, this);
176	      checkSocketIsWritable_ = true;
177	      writeCheckTarget_ = socket;
178	    }
179	  }
180	}
