271	template <typename InputIterator>
272	size_t countSeeder(InputIterator first, InputIterator last)
273	{
274	  size_t res = 0;
275	  for (; first != last; ++first) {
276	    if ((*first)->isActive() && (*first)->isSeeder()) {
277	      ++res;
278	    }
279	  }
280	  return res;
281	}
