297	bool PeerInteractionCommand::executeInternal()
298	{
299	  setNoCheck(false);
300	  bool done = false;
301	  while (!done) {
302	    switch (sequence_) {
303	    case INITIATOR_SEND_HANDSHAKE:
304	      if (!getSocket()->isWritable(0)) {
305	        done = true;
306	        break;
307	      }
308	      disableWriteCheckSocket();
309	      setReadCheckSocket(getSocket());
310	      // socket->setBlockingMode();
311	      setTimeout(std::chrono::seconds(getOption()->getAsInt(PREF_BT_TIMEOUT)));
312	      btInteractive_->initiateHandshake();
313	      sequence_ = INITIATOR_WAIT_HANDSHAKE;
314	      break;
315	    case INITIATOR_WAIT_HANDSHAKE: {
316	      if (btInteractive_->countPendingMessage() > 0) {
317	        btInteractive_->sendPendingMessage();
318	        if (btInteractive_->countPendingMessage() > 0) {
319	          done = true;
320	          break;
321	        }
322	      }
323	      auto handshakeMessage = btInteractive_->receiveHandshake();
324	      if (!handshakeMessage) {
325	        done = true;
326	        break;
327	      }
328	      btInteractive_->doPostHandshakeProcessing();
329	      sequence_ = WIRED;
330	      break;
331	    }
332	    case RECEIVER_WAIT_HANDSHAKE: {
333	      auto handshakeMessage = btInteractive_->receiveAndSendHandshake();
334	      if (!handshakeMessage) {
335	        done = true;
336	        break;
337	      }
338	      btInteractive_->doPostHandshakeProcessing();
339	      sequence_ = WIRED;
340	      break;
341	    }
342	    case WIRED:
343	      btInteractive_->doInteractionProcessing();
344	      if (btInteractive_->countReceivedMessageInIteration() > 0) {
345	        updateKeepAlive();
346	      }
347	
348	      if (getDownloadEngine()
349	              ->getRequestGroupMan()
350	              ->doesOverallDownloadSpeedExceed() ||
351	          requestGroup_->doesDownloadSpeedExceed()) {
352	        disableReadCheckSocket();
353	        setNoCheck(true);
354	      }
355	      else {
356	        setReadCheckSocket(getSocket());
357	      }
358	
359	      done = true;
360	      break;
361	    }
362	  }
363	  if ((btInteractive_->countPendingMessage() > 0 ||
364	       btInteractive_->isSendingMessageInProgress()) &&
365	      !getDownloadEngine()
366	           ->getRequestGroupMan()
367	           ->doesOverallUploadSpeedExceed() &&
368	      !requestGroup_->doesUploadSpeedExceed()) {
369	    setWriteCheckSocket(getSocket());
370	  }
371	  else {
372	    disableWriteCheckSocket();
373	  }
374	
375	  addCommandSelf();
376	  return false;
377	}
